"use strict";(globalThis.webpackChunkproperty_marketplace_docs=globalThis.webpackChunkproperty_marketplace_docs||[]).push([[93],{6555(a){a.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"adminSidebar":[{"type":"link","href":"/p2d-control-tower-docs/id/","label":"Panduan Pengguna P2D Control Tower Online","docId":"intro","unlisted":false},{"type":"category","label":"\u2708\ufe0f Operational Flowmaps","items":[{"type":"link","href":"/p2d-control-tower-docs/id/operational-flow/overview-process","label":"Ringkasan Proses Impor TPS PJT","docId":"operational-flow/overview-process","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/operational-flow/origin-to-airport","label":"Lini Masa Operasional: Bandara Asal ke Bandara CGK","docId":"operational-flow/origin-to-airport","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/operational-flow/warehouse-handling","label":"Penanganan Gudang & Pemeriksaan Kepabeanan","docId":"operational-flow/warehouse-handling","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udccb Manifest Management","items":[{"type":"link","href":"/p2d-control-tower-docs/id/manifest/upload-data","label":"Upload Data (Pemeliharaan File)","docId":"manifest/upload-data","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/manifest/cn-management","label":"Manajemen Consignment Note (CN)","docId":"manifest/cn-management","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/manifest/master-data","label":"Manajemen Master Data (MAWB)","docId":"manifest/master-data","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/manifest/update-bc11","label":"Pembaruan Data Manifes BC11","docId":"manifest/update-bc11","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/manifest/manifest-to-pibk","label":"Manifest to PIBK (Peralihan Data)","docId":"manifest/manifest-to-pibk","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83e\uddee PIBK Module","items":[{"type":"link","href":"/p2d-control-tower-docs/id/pibk/calculation","label":"Modul Kalkulasi Pajak PIBK","docId":"pibk/calculation","unlisted":false},{"type":"link","href":"/p2d-control-tower-docs/id/pibk/document","label":"Dokumen & Pertukaran Data Elektronik PIBK","docId":"pibk/document","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udcca Response Data","items":[{"type":"link","href":"/p2d-control-tower-docs/id/response-data/tracking-responses","label":"Pemantauan Respon Bea Cukai (All Response)","docId":"response-data/tracking-responses","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udcd6 Reference Database","items":[{"type":"link","href":"/p2d-control-tower-docs/id/reference/hs-code-list","label":"Database Referensi Kode HS (HS-CODE)","docId":"reference/hs-code-list","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"intro":{"id":"intro","title":"Panduan Pengguna P2D Control Tower Online","description":"...","sidebar":"adminSidebar"},"manifest/cn-management":{"id":"manifest/cn-management","title":"Manajemen Consignment Note (CN)","description":"Modul CN (Consignment Note / Catatan Konsinyasi) adalah area kerja administratif utama yang digunakan oleh Admin Pabean PJT. Modul ini berfungsi untuk mengelola instruksi pengiriman, melacak riwayat status operasional, mengelola deklarasi pihak terkait, serta menghitung metrik dimensi kargo secara akurat.","sidebar":"adminSidebar"},"manifest/manifest-to-pibk":{"id":"manifest/manifest-to-pibk","title":"Manifest to PIBK (Peralihan Data)","description":"Modul Manifest to PIBK berfungsi sebagai jembatan data yang menghubungkan kluster data manifes kepabeanan langsung ke dalam mesin perhitungan keuangan komoditas. Modul ini memungkinkan operator untuk memeriksa detail data baris barang (Seri Barang) di dalam lot penerbangan, lalu meneruskannya ke antrean keuangan aktif.","sidebar":"adminSidebar"},"manifest/master-data":{"id":"manifest/master-data","title":"Manajemen Master Data (MAWB)","description":"Modul Master data digunakan untuk mengelola data Master Air Waybill (MAWB) pada level utama. Modul ini berfungsi untuk mengonsolidasikan banyak data Consignment Note (CN / House AWB) individual ke dalam satu manifes penerbangan cargo guna memenuhi syarat pengiriman maskapai serta menginisialisasi permohonan pendaftaran Entry Manifest Bea Cukai BC 1.1.","sidebar":"adminSidebar"},"manifest/update-bc11":{"id":"manifest/update-bc11","title":"Pembaruan Data Manifes BC11","description":"Modul Update BC11 adalah portal khusus pelacakan regulasi kepabeanan. Modul ini digunakan oleh Admin Manifes untuk mencatat, memperbarui, dan memantau secara manual nomor BC 1.1 (Manifes Pajak Impor) resmi serta Nomor Pengajuan AJU setelah kantor Bea Cukai merilis nomor pendaftaran resmi kargo pesawat yang tiba.","sidebar":"adminSidebar"},"manifest/upload-data":{"id":"manifest/upload-data","title":"Upload Data (Pemeliharaan File)","description":"Modul Upload Data memungkinkan tim Trafik dan Admin Manifes untuk melakukan inisialisasi awal data pengiriman kargo pesawat menggunakan templat Excel standar. Tahap ini mengawali tahapan operasional Pre-Alert.","sidebar":"adminSidebar"},"operational-flow/origin-to-airport":{"id":"operational-flow/origin-to-airport","title":"Lini Masa Operasional: Bandara Asal ke Bandara CGK","description":"Bagian ini menjelaskan batas waktu kritis dan tanggung jawab administratif yang diperlukan saat kargo beralih dari bandara asal internasional menuju Gudang Lini-1 Bandara Soekarno-Hatta (CGK).","sidebar":"adminSidebar"},"operational-flow/overview-process":{"id":"operational-flow/overview-process","title":"Ringkasan Proses Impor TPS PJT","description":"Bagian ini membahas pemetaan integrasi sistem end-to-end untuk Proses Impor TPS PJT di MSA Kargo. Alur kerja ini melacak pergerakan pengiriman dari bandara asal, validasi pabean, penanganan gudang, hingga pengiriman akhir menggunakan armada transportasi.","sidebar":"adminSidebar"},"operational-flow/warehouse-handling":{"id":"operational-flow/warehouse-handling","title":"Penanganan Gudang & Pemeriksaan Kepabeanan","description":"Bagian ini merinci operasional internal gudang, logistik tata letak penyortiran, dan titik pemeriksaan validasi pabean di Gudang TPS PJT MSA.","sidebar":"adminSidebar"},"pibk/calculation":{"id":"pibk/calculation","title":"Modul Kalkulasi Pajak PIBK","description":"Modul PIBK Calculation adalah mesin pembukuan keuangan dan penilaian nilai pabean inti dari platform Control Tower. Modul ini dikelola oleh Admin Pabean PJT untuk menghitung besaran pajak impor, nilai konversi mata uang kurs, mengaudit komponen Biaya, Asuransi, dan Navigasi (CIF), serta menetapkan akumulasi total tagihan setoran pajak negara.","sidebar":"adminSidebar"},"pibk/document":{"id":"pibk/document","title":"Dokumen & Pertukaran Data Elektronik PIBK","description":"Modul Document berfungsi sebagai gerbang pertukaran data elektronik (EDI / Electronic Data Interchange) resmi untuk Modul PIBK. Modul ini digunakan oleh tim pabean untuk menyusun data perpajakan kargo ke dalam skema file elektronik standar, mengirimkan deklarasi otomatis, serta menarik data respon kepabeanan dari Bea Cukai.","sidebar":"adminSidebar"},"reference/hs-code-list":{"id":"reference/hs-code-list","title":"Database Referensi Kode HS (HS-CODE)","description":"Modul HS-CODE List berfungsi sebagai direktori pencarian master utama sistem untuk kode klasifikasi tarif komoditas barang berdasarkan data resmi Bea Cukai Indonesia. Modul referensi ini bertindak sebagai tempat penyimpanan data otomatis yang menyuplai nilai persentase bea masuk, pajak, dan tarif pabean langsung ke kolom data Manajemen Manifest dan Modul PIBK.","sidebar":"adminSidebar"},"response-data/billing":{"id":"response-data/billing","title":"billing","description":""},"response-data/tracking-responses":{"id":"response-data/tracking-responses","title":"Pemantauan Respon Bea Cukai (All Response)","description":"Modul dasbor All Response adalah pusat pelacakan regulasi khusus di bawah kategori menu Response Data. Modul ini berfungsi sebagai pusat audit terpadu yang merangkum, menyaring, dan mencatat seluruh berkas respon elektronik, peringatan pembatasan, nota perpajakan, serta surat persetujuan pengeluaran kargo yang dikirim dari jaringan sistem Bea dan Cukai.","sidebar":"adminSidebar"}}}}')}}]);